exercicios.web_js:
window.tasks = ["Study Python", "Review PRs", "Deploy"];
window.addEventListener("DOMContentLoaded", function () {
  var ul = document.getElementById("list");
  if (!ul) return;
  window.tasks.forEach(function (t) {
    var li = document.createElement("li");
    li.textContent = t;
    ul.appendChild(li);
  });
});

