exercicios.solucao_js:
window.products = [
  { name: "Keyboard", price: "$120.00" },
  { name: "Mouse", price: "$80.00" },
  { name: "Monitor", price: "$950.00" }
];

function render(list) {
  var target = document.getElementById("list");
  var html = "";
  list.forEach(function (p) {
    html += "<div class='card'><span class='name'>" + p.name +
      "</span><span class='price'>" + p.price + "</span></div>";
  });
  target.innerHTML = html;
}

render(window.products);

