/* Scene: the Coral Emporium counter (coral district, nightfall) */
body{margin:0;min-height:100vh;font-family:"Segoe UI",system-ui,sans-serif;color:#ffe9dc;background:linear-gradient(180deg,#221331 0%,#45213e 45%,#83394a 80%,#c25f4a 100%)}
.shop{max-width:400px;margin:22px auto;padding:0 14px;text-align:center}
.sign{margin:0 0 14px;font-size:20px;font-weight:700;letter-spacing:.12em;text-transform:uppercase;color:#ffe3d4;text-shadow:0 0 16px rgba(255,120,90,.8),0 0 40px rgba(255,120,90,.35)}
.counter{padding:16px;border-radius:16px;border:1px solid rgba(255,150,110,.35);background:linear-gradient(180deg,rgba(255,244,224,.06),rgba(10,4,14,.30));box-shadow:0 0 34px rgba(255,110,80,.16)}
.product{display:flex;align-items:center;gap:12px;padding:10px 12px;border-radius:12px;text-align:left;border:1px solid rgba(255,214,170,.18);background:rgba(255,244,224,.05)}
/* the lantern: a warm near-white core with a soft coral halo */
.lantern{flex:none;width:34px;height:44px;border-radius:8px 8px 11px 11px;border:1px solid rgba(255,228,190,.6);background:radial-gradient(circle at 50% 42%,#fff4e0 0 5px,rgba(255,179,92,.85) 45%,rgba(96,38,40,.95) 78%);box-shadow:0 0 22px rgba(255,170,110,.6);animation:shine 4s ease-in-out infinite}
